<?php namespace App\Http\Controllers\Api; use App\Http\Resources\CatechismClassResource; use App\Models\AttendanceSession; use Illuminate\Http\Request; class TeacherController extends ApiController { public function classes(Request $request){$teacher=$request->user()->teacherProfile;abort_unless($teacher,403);$classes=$teacher->classes()->with(['academicYear','level','classroom','schedules'])->withCount('children')->paginate(15);return $this->success(CatechismClassResource::collection($classes),'Fetched classes',['current_page'=>$classes->currentPage(),'last_page'=>$classes->lastPage(),'per_page'=>$classes->perPage(),'total'=>$classes->total()]);} public function dashboard(Request $request){$teacher=$request->user()->teacherProfile;abort_unless($teacher,403);$classes=$teacher->classes()->with(['academicYear','level','classroom','schedules'])->withCount('children')->get();$ids=$classes->pluck('id');$sessions=AttendanceSession::whereIn('catechism_class_id',$ids)->with('catechismClass')->latest('held_at')->take(5)->get();return $this->success(['teacher'=>['id'=>$teacher->id,'name'=>$request->user()->name],'summary'=>['class_count'=>$classes->count(),'child_count'=>$classes->sum('children_count'),'pending_leave_requests'=>0,'today_sessions'=>0],'classes'=>CatechismClassResource::collection($classes),'recent_attendance_sessions'=>$sessions,'upcoming_sessions'=>$classes->flatMap->schedules,'recent_announcements'=>[]]);} }
